import React from 'react';
import './TrainingPlansPage.css'; // Custom styles for aesthetics

const TrainingPlansPage = () => {
  const plans = [
    {
      level: "Beginner",
      description: "Ideal for those new to triathlons, focusing on building endurance and getting comfortable with all three disciplines.",
      duration: "12 weeks",
    },
    {
      level: "Intermediate",
      description: "Perfect for triathletes with some experience who want to improve their times and performance.",
      duration: "16 weeks",
    },
    {
      level: "Advanced",
      description: "For seasoned athletes looking to compete at a high level or prepare for long-distance events like Ironman.",
      duration: "20 weeks",
    },
  ];

  return (
    <div className="training-plans">
      <header className="training-header">
        <h1>Training Plans</h1>
        <p>Choose the perfect plan to achieve your triathlon goals.</p>
      </header>
      <section className="plan-list">
        {plans.map((plan, index) => (
          <div className="plan-card" key={index}>
            <h2>{plan.level}</h2>
            <p>{plan.description}</p>
            <p><strong>Duration:</strong> {plan.duration}</p>
            <button className="plan-button">View Details</button>
          </div>
        ))}
      </section>
    </div>
  );
};

export default TrainingPlansPage;
